CREATE TABLE klanten AS SELECT * FROM (VALUES
  (1, 'Anna', 'Utrecht'), (2, 'Bram', 'Breda'), (3, 'Cor', 'Delft')
) t(klant_id, naam, plaats);

-- wijzigingen sinds de vorige run, met volgnummer
CREATE TABLE wijzigingen AS SELECT * FROM (VALUES
  (2, 'Bram', 'Tilburg', 'UPDATE', 11),
  (2, 'Bram', 'Eindhoven', 'UPDATE', 12),
  (3, NULL, NULL, 'DELETE', 13),
  (4, 'Dewi', 'Zwolle', 'INSERT', 14)
) t(klant_id, naam, plaats, operatie, volgnr);

MERGE INTO klanten AS t
USING (
  SELECT * FROM wijzigingen
  QUALIFY row_number() OVER (PARTITION BY klant_id ORDER BY volgnr DESC) = 1
) AS w
ON t.klant_id = w.klant_id
WHEN MATCHED AND w.operatie = 'DELETE' THEN DELETE
WHEN MATCHED THEN UPDATE SET naam = w.naam, plaats = w.plaats
WHEN NOT MATCHED AND w.operatie <> 'DELETE' THEN
  INSERT (klant_id, naam, plaats) VALUES (w.klant_id, w.naam, w.plaats);

SELECT * FROM klanten ORDER BY klant_id;
